CREATE TABLE IF NOT EXISTS user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified INTEGER NOT NULL DEFAULT 0, image TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS session (id TEXT PRIMARY KEY, expires_at INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, ip_address TEXT, user_agent TEXT, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_user ON session(user_id);
CREATE TABLE IF NOT EXISTS account (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, provider_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, access_token TEXT, refresh_token TEXT, id_token TEXT, access_token_expires_at INTEGER, refresh_token_expires_at INTEGER, scope TEXT, password TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER, updated_at INTEGER);
CREATE TABLE IF NOT EXISTS wallets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id), name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 80), opening INTEGER NOT NULL CHECK(typeof(opening)='integer' AND abs(opening)<=999999999999), currency TEXT NOT NULL DEFAULT 'SGD' CHECK(currency='SGD'), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), UNIQUE(id,user_id));
CREATE TABLE IF NOT EXISTS entries (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id), kind TEXT NOT NULL CHECK(kind IN ('income','expense','transfer')), date TEXT NOT NULL CHECK(date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), description TEXT NOT NULL CHECK(length(description) BETWEEN 1 AND 200), amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0 AND amount<=999999999999), wallet_id TEXT NOT NULL, destination_id TEXT, category TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', fingerprint TEXT, FOREIGN KEY(wallet_id,user_id) REFERENCES wallets(id,user_id), FOREIGN KEY(destination_id,user_id) REFERENCES wallets(id,user_id), CHECK((kind='transfer' AND destination_id IS NOT NULL AND destination_id<>wallet_id AND category='Transfer') OR (kind<>'transfer' AND destination_id IS NULL)), UNIQUE(user_id,fingerprint));
CREATE INDEX IF NOT EXISTS entries_month ON entries(user_id,date,kind);
CREATE INDEX IF NOT EXISTS entries_wallet ON entries(wallet_id);
CREATE INDEX IF NOT EXISTS entries_destination ON entries(destination_id);
CREATE TABLE IF NOT EXISTS budgets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id), month TEXT NOT NULL, category TEXT NOT NULL, amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0 AND amount<=999999999999), UNIQUE(user_id,month,category));
CREATE TABLE IF NOT EXISTS subscriptions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id), name TEXT NOT NULL, amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0 AND amount<=999999999999), wallet_id TEXT NOT NULL, recurrence TEXT NOT NULL CHECK(recurrence IN ('weekly','monthly','yearly')), next_due TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','paused','cancelled')), FOREIGN KEY(wallet_id,user_id) REFERENCES wallets(id,user_id));
CREATE TABLE IF NOT EXISTS goals (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id), name TEXT NOT NULL, amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0 AND amount<=999999999999), target_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contributions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id), goal_id TEXT NOT NULL REFERENCES goals(id) ON DELETE CASCADE, amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0 AND amount<=999999999999), date TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS contribution_goal ON contributions(user_id,goal_id,date);
CREATE TABLE IF NOT EXISTS receipts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id), entry_id TEXT NOT NULL UNIQUE REFERENCES entries(id) ON DELETE CASCADE, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL);
